import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { addToCart, toggleWishlist } from '../services/api';
import { isAuthenticated } from '../util/auth';
import useToast from '../hooks/useToast';
import { useCart } from '../context/CartContext';

const ProductCard = ({ product, onCartUpdate, index = 0, isDetailView = false }) => {
  const [loading, setLoading] = useState(false);
  const [quantity, setQuantity] = useState(1);
  const [isWishlisted, setIsWishlisted] = useState(false);
  const [wishlistLoading, setWishlistLoading] = useState(false);

  const { showSuccessToast, showErrorToast } = useToast();
  const { updateCartCount } = useCart();
  const navigate = useNavigate();

  const animationDelay = `${index * 0.06}s`;

  const getCategoryEmoji = (category) => {
    const emojis = {
      milk: '🥛',
      ghee: '🍯',
      cheese: '🧀',
      butter: '🧈',
      curd: '🥣',
      paneer: '🧊',
      cream: '🍦',
      yogurt: '🍶',
      lassi: '🥤',
      buttermilk: '🫙',
      sweets: '🍬',
      cake: '🍰'
    };
    return emojis[category] || '🥛';
  };

  const getCategoryPill = (category) => {
    const classes = {
      milk: 'bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-200',
      ghee: 'bg-amber-50 text-amber-700 dark:bg-amber-900/30 dark:text-amber-200',
      cheese: 'bg-yellow-50 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-200',
      butter: 'bg-orange-50 text-orange-700 dark:bg-orange-900/30 dark:text-orange-200',
      curd: 'bg-green-50 text-green-700 dark:bg-green-900/30 dark:text-green-200',
      paneer: 'bg-purple-50 text-purple-700 dark:bg-purple-900/30 dark:text-purple-200',
      cream: 'bg-pink-50 text-pink-700 dark:bg-pink-900/30 dark:text-pink-200',
      yogurt: 'bg-teal-50 text-teal-700 dark:bg-teal-900/30 dark:text-teal-200',
      lassi: 'bg-cyan-50 text-cyan-700 dark:bg-cyan-900/30 dark:text-cyan-200',
      buttermilk: 'bg-lime-50 text-lime-700 dark:bg-lime-900/30 dark:text-lime-200',
      sweets: 'bg-rose-50 text-rose-700 dark:bg-rose-900/30 dark:text-rose-200',
      cake: 'bg-fuchsia-50 text-fuchsia-700 dark:bg-fuchsia-900/30 dark:text-fuchsia-200'
    };
    return classes[category] || 'bg-gray-100 text-gray-700 dark:bg-white/10 dark:text-gray-200';
  };

  const clampQty = (nextQty) => {
    const maxQty = Math.max(1, Number(product?.stock || 1));
    return Math.max(1, Math.min(maxQty, nextQty));
  };

  const handleAddToCart = async (e) => {
    e.preventDefault();
    e.stopPropagation();

    if (!isAuthenticated()) {
      window.location.href = '/cart';
      return;
    }

    try {
      setLoading(true);
      await addToCart(product._id, quantity);
      onCartUpdate?.();
      updateCartCount();
      showSuccessToast(`${product.name} added to cart successfully!`);
    } catch (error) {
      if (!error.response) showErrorToast('Network error. Please check your connection.');
      else showErrorToast(error.response?.data?.message || 'Error adding to cart. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleToggleWishlist = async (e) => {
    e.preventDefault();
    e.stopPropagation();

    if (!isAuthenticated()) {
      window.location.href = '/login';
      return;
    }

    try {
      setWishlistLoading(true);
      await toggleWishlist(product._id);
      setIsWishlisted((v) => !v);
    } catch (error) {
      showErrorToast('Wishlist error. Please try again.');
    } finally {
      setWishlistLoading(false);
    }
  };

  const handleCardClick = () => {
    if (isDetailView) return;
    navigate(`/product/${product._id}`);
  };

  const ratingValue = Number(product?.ratings || 0);
  const ratingText = ratingValue > 0 ? ratingValue.toFixed(1) : 'New';
  const reviewsCount = Number(product?.numReviews || 0);

  return (
    <div
      className={`group h-full bg-white dark:bg-gray-900 border border-gray-200/70 dark:border-white/10 rounded-2xl overflow-hidden transition-shadow duration-200 hover:shadow-lg hover:shadow-black/5 dark:hover:shadow-black/30 ${
        isDetailView ? '' : 'cursor-pointer'
      }`}
      style={{ animationDelay }}
      onClick={handleCardClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter') handleCardClick();
      }}
    >
      <div className="relative bg-white dark:bg-gray-900">
        <div className="aspect-square w-full overflow-hidden">
          {product?.image ? (
            <img
              src={product.image}
              alt={product.name}
              className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-[1.03]"
              onError={(e) => {
                e.currentTarget.style.display = 'none';
              }}
              loading="lazy"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-gray-100 to-gray-200 dark:from-white/5 dark:to-white/10">
              <span className="text-6xl">{getCategoryEmoji(product?.category)}</span>
            </div>
          )}
        </div>

        <button
          onClick={handleToggleWishlist}
          disabled={wishlistLoading}
          className={`absolute top-3 right-3 w-9 h-9 rounded-full flex items-center justify-center backdrop-blur border transition-colors ${
            isWishlisted
              ? 'bg-red-500 text-white border-red-500 shadow-md shadow-red-500/20'
              : 'bg-white/90 dark:bg-gray-900/80 text-gray-700 dark:text-gray-200 border-gray-200/70 dark:border-white/10 hover:text-red-500'
          }`}
          title={isWishlisted ? 'Remove from wishlist' : 'Add to wishlist'}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="h-5 w-5"
            fill={isWishlisted ? 'currentColor' : 'none'}
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"
            />
          </svg>
        </button>
      </div>

      <div className="p-4 flex flex-col h-[15rem]">
        <div className="flex items-start justify-between gap-2">
          <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold ${getCategoryPill(product?.category)}`}>
            <span aria-hidden>{getCategoryEmoji(product?.category)}</span>
            <span className="capitalize">{product?.category || 'product'}</span>
          </span>

          {product?.stock === 0 ? (
            <span className="text-xs font-semibold px-2.5 py-1 rounded-full bg-red-50 text-red-700 dark:bg-red-900/30 dark:text-red-200">
              Out of stock
            </span>
          ) : null}
        </div>

        <div className="mt-2">
          <div className="text-sm text-gray-500 dark:text-gray-400">{product?.brand || 'MilkMitra'}</div>
          <div className="mt-0.5 font-semibold text-gray-900 dark:text-white leading-snug line-clamp-2">{product?.name}</div>
        </div>

        <div className="mt-2 flex items-center gap-2">
          <div className="inline-flex items-center gap-1 px-2 py-1 rounded-md bg-green-600 text-white text-xs font-bold">
            <span>{ratingText}</span>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" viewBox="0 0 20 20" fill="currentColor">
              <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.176 0l-2.8 2.034c-.784.57-1.838-.197-1.54-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.719c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
            </svg>
          </div>
          <div className="text-xs text-gray-600 dark:text-gray-400">{reviewsCount > 0 ? `${reviewsCount} reviews` : 'No reviews yet'}</div>
        </div>

        <div className="mt-3 flex items-baseline gap-2">
          <div className="text-xl font-extrabold text-gray-900 dark:text-white">₹{product?.price}</div>
          <div className="text-sm text-gray-500 dark:text-gray-400">/{product?.unit || 'unit'}</div>
        </div>

        <div className="mt-1 text-xs text-gray-500 dark:text-gray-400">
          {product?.stock > 0 ? (
            <span>
              <span className="font-semibold text-green-700 dark:text-green-300">In stock</span> • delivery in 30–60 mins
            </span>
          ) : (
            <span>Currently unavailable</span>
          )}
        </div>

        <div className="mt-auto pt-4 flex items-center gap-2">
          <div className="flex items-center border border-gray-200 dark:border-white/10 rounded-xl overflow-hidden bg-gray-50 dark:bg-white/5">
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                setQuantity((q) => clampQty(q - 1));
              }}
              className="w-9 h-9 grid place-items-center text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-white/10"
              aria-label="Decrease quantity"
            >
              −
            </button>
            <div className="w-10 text-center text-sm font-bold text-gray-900 dark:text-white">{quantity}</div>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                setQuantity((q) => clampQty(q + 1));
              }}
              className="w-9 h-9 grid place-items-center text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-white/10"
              aria-label="Increase quantity"
            >
              +
            </button>
          </div>

          <button
            onClick={handleAddToCart}
            disabled={loading || product?.stock === 0}
            className={`flex-1 h-10 rounded-xl font-semibold transition-all ${
              product?.stock === 0
                ? 'bg-gray-200 text-gray-500 dark:bg-white/10 dark:text-gray-400 cursor-not-allowed'
                : 'bg-yellow-400 hover:bg-yellow-500 text-gray-900 shadow-sm'
            }`}
          >
            {loading ? 'Adding…' : product?.stock === 0 ? 'Out of Stock' : 'Add to Cart'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductCard;
